class Torch:
    def __init__(self, fuel):
        self.fuel = fuel

    def burn(self):
        self.fuel -= 1


def torch_after(fuel, times):
    torch = Torch(fuel)
    for _ in range(times):
        torch.burn()
    return torch.fuel

